mapper.select:
SELECT f.*, b.base_name,
CASE
    WHEN f.target_type = 'pond' THEN COALESCE(po.pond_name, CONCAT('塘口#', f.target_id))
    WHEN f.target_type = 'cage' THEN COALESCE(ci.cage_name, CONCAT('网箱#', f.target_id))
    WHEN f.target_type = 'vsl' THEN COALESCE(vi.vsl_name, CONCAT('工船#', f.target_id))
    ELSE CONCAT(f.target_type, '#', f.target_id)
END AS target_name
FROM feeding_record f
LEFT JOIN base_info b ON f.base_id = b.id
LEFT JOIN pond_info po ON f.target_id = po.id AND f.target_type = 'pond'
LEFT JOIN cage_info ci ON f.target_id = ci.id AND f.target_type = 'cage'
LEFT JOIN vsl_info vi ON f.target_id = vi.id AND f.target_type = 'vsl'

    AND f.base_id = #{query.baseId}
    AND f.target_id = #{query.targetId}
    AND f.target_type = #{query.targetType}
    AND f.feed_type = #{query.feedType}
    AND f.source = #{query.source}
    AND f.verify_status = #{query.verifyStatus}
    AND action_time >= #{query.actionTimeStart}
    AND action_time <= #{query.actionTimeEnd}

ORDER BY f.action_time DESC
